-- public.bury_treasure(p_world uuid, p_uid uuid, p_ql double precision, p_x double precision, p_y double precision)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.bury_treasure(p_world uuid, p_uid uuid, p_ql double precision, p_x double precision, p_y double precision)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
declare v_spot record; v_tier treasure_def; v_id bigint;
begin
  select * into v_spot from treasure_spot_for(p_world, p_x, p_y, (treasure_tier(p_ql)).guard);
  -- Nowhere to put it. Better no map than a map to the sea.
  if v_spot.x is null then return null; end if;
  v_tier := treasure_tier(p_ql);
  v_id := give(p_world, p_uid, 'treasure_map', 1, p_ql, v_tier.id);
  insert into treasure (item_id, world_id, x, y, tier, finder)
    values (v_id, p_world, v_spot.x, v_spot.y, v_tier.id, p_uid);
  perform journal_note(p_world, p_uid, 'map');
  perform tell(p_world, p_uid, 'Found: '
    || v_tier.name || ', QL ' || to_char(p_ql, 'FM990.0')
    || '. Read it for the distance to its hoard.', 'skill');
  return v_id;
end $function$
